// Package tpmkey manages a non-exportable ECDSA P-256 signing key that lives
// inside a TPM 2.0 and uses it to mint ES256 JWTs. The private half of the key
// is generated by the TPM and never leaves it; callers only ever see the public
// key and signatures.
package tpmkey

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"

	"github.com/google/go-tpm/tpm2"
	"github.com/google/go-tpm/tpm2/transport"
)

// DefaultHandle is the persistent owner-hierarchy handle the signing key is
// stored at unless another is specified.
const DefaultHandle tpm2.TPMHandle = 0x81010101

// signingTemplate describes an ECDSA P-256 / SHA-256 signing key that is bound
// to this TPM (FixedTPM), cannot be duplicated to another parent
// (FixedParent), and whose private material was generated inside the TPM
// (SensitiveDataOrigin). Together these mean the private key cannot be
// exported in any form.
var signingTemplate = tpm2.TPMTPublic{
	Type:    tpm2.TPMAlgECC,
	NameAlg: tpm2.TPMAlgSHA256,
	ObjectAttributes: tpm2.TPMAObject{
		FixedTPM:            true,
		FixedParent:         true,
		SensitiveDataOrigin: true,
		UserWithAuth:        true,
		SignEncrypt:         true,
	},
	Parameters: tpm2.NewTPMUPublicParms(tpm2.TPMAlgECC, &tpm2.TPMSECCParms{
		Scheme: tpm2.TPMTECCScheme{
			Scheme: tpm2.TPMAlgECDSA,
			Details: tpm2.NewTPMUAsymScheme(tpm2.TPMAlgECDSA, &tpm2.TPMSSigSchemeECDSA{
				HashAlg: tpm2.TPMAlgSHA256,
			}),
		},
		CurveID: tpm2.TPMECCNistP256,
	}),
}

// Create generates a new signing key inside the TPM under a freshly derived
// storage root key and persists it at handle. It refuses to overwrite a key
// that already exists at handle.
func Create(tpm transport.TPM, handle tpm2.TPMHandle) (*ecdsa.PublicKey, error) {
	if _, err := (tpm2.ReadPublic{ObjectHandle: handle}).Execute(tpm); err == nil {
		return nil, fmt.Errorf("a key already exists at handle 0x%x", uint32(handle))
	}

	srk, err := tpm2.CreatePrimary{
		PrimaryHandle: tpm2.TPMRHOwner,
		InPublic:      tpm2.New2B(tpm2.ECCSRKTemplate),
	}.Execute(tpm)
	if err != nil {
		return nil, fmt.Errorf("failed to create storage root key: %w", err)
	}
	defer tpm2.FlushContext{FlushHandle: srk.ObjectHandle}.Execute(tpm)
	parent := tpm2.NamedHandle{Handle: srk.ObjectHandle, Name: srk.Name}

	created, err := tpm2.Create{
		ParentHandle: parent,
		InPublic:     tpm2.New2B(signingTemplate),
	}.Execute(tpm)
	if err != nil {
		return nil, fmt.Errorf("failed to create signing key: %w", err)
	}

	loaded, err := tpm2.Load{
		ParentHandle: parent,
		InPrivate:    created.OutPrivate,
		InPublic:     created.OutPublic,
	}.Execute(tpm)
	if err != nil {
		return nil, fmt.Errorf("failed to load signing key: %w", err)
	}
	defer tpm2.FlushContext{FlushHandle: loaded.ObjectHandle}.Execute(tpm)

	if _, err := (tpm2.EvictControl{
		Auth:             tpm2.TPMRHOwner,
		ObjectHandle:     tpm2.NamedHandle{Handle: loaded.ObjectHandle, Name: loaded.Name},
		PersistentHandle: handle,
	}).Execute(tpm); err != nil {
		return nil, fmt.Errorf("failed to persist signing key at handle 0x%x: %w", uint32(handle), err)
	}

	pub, _, err := Public(tpm, handle)
	return pub, err
}

// Public reads the public half of the key at handle and verifies that it has
// the non-exportable signing attributes this package relies on.
func Public(tpm transport.TPM, handle tpm2.TPMHandle) (*ecdsa.PublicKey, tpm2.TPM2BName, error) {
	rsp, err := tpm2.ReadPublic{ObjectHandle: handle}.Execute(tpm)
	if err != nil {
		return nil, tpm2.TPM2BName{}, fmt.Errorf("failed to read key at handle 0x%x: %w", uint32(handle), err)
	}
	public, err := rsp.OutPublic.Contents()
	if err != nil {
		return nil, tpm2.TPM2BName{}, fmt.Errorf("failed to decode public area: %w", err)
	}

	attrs := public.ObjectAttributes
	if public.Type != tpm2.TPMAlgECC || !attrs.FixedTPM || !attrs.FixedParent || !attrs.SensitiveDataOrigin || !attrs.SignEncrypt || attrs.Decrypt || attrs.Restricted {
		return nil, tpm2.TPM2BName{}, errors.New("key is not a non-exportable, unrestricted ECC signing key")
	}
	params, err := public.Parameters.ECCDetail()
	if err != nil {
		return nil, tpm2.TPM2BName{}, err
	}
	if params.CurveID != tpm2.TPMECCNistP256 {
		return nil, tpm2.TPM2BName{}, errors.New("key is not on the NIST P-256 curve")
	}

	pub, err := tpm2.Pub(*public)
	if err != nil {
		return nil, tpm2.TPM2BName{}, err
	}
	ecPub, ok := pub.(*ecdsa.PublicKey)
	if !ok {
		return nil, tpm2.TPM2BName{}, errors.New("key is not an ECDSA key")
	}
	return ecPub, rsp.Name, nil
}

// sign asks the TPM to sign a SHA-256 digest and returns the signature in the
// fixed-width r||s form JWS ES256 requires.
func sign(tpm transport.TPM, handle tpm2.TPMHandle, name tpm2.TPM2BName, digest []byte) ([]byte, error) {
	rsp, err := tpm2.Sign{
		KeyHandle:  tpm2.NamedHandle{Handle: handle, Name: name},
		Digest:     tpm2.TPM2BDigest{Buffer: digest},
		InScheme:   tpm2.TPMTSigScheme{Scheme: tpm2.TPMAlgNull},
		Validation: tpm2.TPMTTKHashCheck{Tag: tpm2.TPMSTHashCheck, Hierarchy: tpm2.TPMRHNull},
	}.Execute(tpm)
	if err != nil {
		return nil, fmt.Errorf("TPM failed to sign: %w", err)
	}
	ecSig, err := rsp.Signature.Signature.ECDSA()
	if err != nil {
		return nil, err
	}
	return encodeES256(ecSig.SignatureR.Buffer, ecSig.SignatureS.Buffer)
}

// encodeES256 left-pads r and s to 32 bytes each. TPMs may return them with
// leading zero bytes stripped, but JWS requires the fixed-width form.
func encodeES256(r, s []byte) ([]byte, error) {
	if len(r) > 32 || len(s) > 32 {
		return nil, errors.New("TPM returned an oversized ECDSA signature")
	}
	out := make([]byte, 64)
	copy(out[32-len(r):32], r)
	copy(out[64-len(s):], s)
	return out, nil
}

// JWK is the public JSON Web Key for a P-256 key.
type JWK struct {
	Kty string `json:"kty"`
	Crv string `json:"crv"`
	X   string `json:"x"`
	Y   string `json:"y"`
	Alg string `json:"alg"`
	Use string `json:"use"`
	Kid string `json:"kid"`
}

// PublicJWK returns the JWK for pub. The kid is the RFC 7638 thumbprint of the
// key, so it is stable for a given key and unique per host.
func PublicJWK(pub *ecdsa.PublicKey) (JWK, error) {
	if pub.Curve != elliptic.P256() {
		return JWK{}, errors.New("key is not on the NIST P-256 curve")
	}
	raw, err := pub.Bytes() // 0x04 || X || Y
	if err != nil {
		return JWK{}, err
	}
	enc := base64.RawURLEncoding
	x, y := enc.EncodeToString(raw[1:33]), enc.EncodeToString(raw[33:65])
	// RFC 7638: required members only, lexicographic order, no whitespace.
	thumb := sha256.Sum256(fmt.Appendf(nil, `{"crv":"P-256","kty":"EC","x":"%s","y":"%s"}`, x, y))
	return JWK{
		Kty: "EC",
		Crv: "P-256",
		X:   x,
		Y:   y,
		Alg: "ES256",
		Use: "sig",
		Kid: enc.EncodeToString(thumb[:]),
	}, nil
}

// JWKS renders a JWK set containing the given keys, in the form accepted by
// `gcloud iam workload-identity-pools providers create-oidc --jwk-json-path`.
func JWKS(keys ...JWK) ([]byte, error) {
	return json.MarshalIndent(struct {
		Keys []JWK `json:"keys"`
	}{Keys: keys}, "", "  ")
}
